// #39 (WS4) | Writes the results matrix as markdown, generated by code. Java 11 only.
package io.sajeev.interop;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Targets as columns, checks as rows. The file says what was run, never more. */
public final class MatrixWriter {

    private final Map<String, List<CheckResult>> byTarget = new LinkedHashMap<>();

    /** @param target the device or build name @param results its check results */
    public void add(String target, List<CheckResult> results) {
        byTarget.put(target, results);
    }

    /** @return the matrix as markdown */
    public String markdown(String generatedOn) {
        List<String> checks = new ArrayList<>();
        for (List<CheckResult> rs : byTarget.values()) {
            for (CheckResult r : rs) {
                if (!checks.contains(r.name())) {
                    checks.add(r.name());
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        sb.append("# Interoperability results\n\nGenerated by the interop harness (`io.sajeev.interop`, run with `eval/rig/run_interop.sh`) on ").append(generatedOn)
                .append(". Do not edit by hand.\n\n| Check |");
        for (String t : byTarget.keySet()) {
            sb.append(' ').append(t).append(" |");
        }
        sb.append("\n|---|");
        for (int i = 0; i < byTarget.size(); i++) {
            sb.append("---|");
        }
        sb.append('\n');
        for (String c : checks) {
            sb.append("| ").append(c).append(" |");
            for (List<CheckResult> rs : byTarget.values()) {
                String cell = "not run";
                for (CheckResult r : rs) {
                    if (r.name().equals(c)) {
                        cell = r.status() + ": " + r.detail().replace("|", "/");
                    }
                }
                sb.append(' ').append(cell).append(" |");
            }
            sb.append('\n');
        }
        return sb.toString();
    }
}
